dist/Components/NcAppNavigationItem.js'\nimport NcAppContent from '@nextcloud/vue/dist/Components/NcAppContent.js'\nimport NcButton from '@nextcloud/vue/dist/Components/NcButton.js'\nimport NcEmptyContent from '@nextcloud/vue/dist/Components/NcEmptyContent.js'\nimport ClockIcon from 'vue-material-design-icons/Clock.vue'\nimport CalendarIcon from 'vue-material-design-icons/Calendar.vue'\nimport AccountGroupIcon from 'vue-material-design-icons/AccountGroup.vue'\nimport CheckDecagramIcon from 'vue-material-design-icons/CheckDecagram.vue'\nimport CogIcon from 'vue-material-design-icons/Cog.vue'\nimport AccountCogIcon from 'vue-material-design-icons/AccountCog.vue'\nimport AlertIcon from 'vue-material-design-icons/Alert.vue'\nimport ShieldIcon from 'vue-material-design-icons/Shield.vue'\nimport { mapGetters, mapActions } from 'vuex'\n\nexport default {\n\tname: 'App',\n\tcomponents: {\n\t\tNcContent,\n\t\tNcAppNavigation,\n\t\tNcAppNavigationItem,\n\t\tNcAppContent,\n\t\tNcButton,\n\t\tNcEmptyContent,\n\t\tClockIcon,\n\t\tCalendarIcon,\n\t\tAccountGroupIcon,\n\t\tCheckDecagramIcon,\n\t\tCogIcon,\n\t\tAccountCogIcon,\n\t\tAlertIcon,\n\t\tShieldIcon,\n\t},\n\tcomputed: {\n\t\t...mapGetters('permissions', ['isEmployee', 'isAdmin', 'isHrManager', 'hasEmployees', 'canManageSettings', 'canApprove']),\n\t},\n\tcreated() {\n\t\tthis.initializeApp()\n\t},\n\tmethods: {\n\t\t...mapActions('employees', ['fetchCurrentEmployee', 'fetchFederalStates']),\n\t\t...mapActions('projects', ['fetchProjects']),\n\t\t...mapActions('absences', ['fetchAbsenceTypes']),\n\t\tasync initializeApp() {\n\t\t\t// Load initial data\n\t\t\tawait Promise.all([\n\t\t\t\tthis.fetchFederalStates(),\n\t\t\t\tthis.fetchProjects(),\n\t\t\t\tthis.fetchAbsenceTypes(),\n\t\t\t])\n\n\t\t\t// Only fetch employee data if user has an employee profile\n\t\t\tif (this.isEmployee) {\n\t\t\t\tawait this.fetchCurrentEmployee()\n\t\t\t}\n\t\t},\n\t},\n}\n</script>\n\n<style scoped>\n.no-employee-warning {\n\tdisplay: flex;\